CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_profiles (user_id uuid PRIMARY KEY REFERENCES users(id), display_name text NOT NULL, battle_net_account_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guilds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, region text NOT NULL CHECK (region IN ('eu','us')), realm_slug text NOT NULL, realm_name text NOT NULL, character_realm_type text NOT NULL CHECK (character_realm_type IN ('era','anniversary')), content_version text NOT NULL CHECK (content_version IN ('era','tbc')), faction text NOT NULL CHECK (faction IN ('Alliance','Horde')), description text NOT NULL DEFAULT '', owner_user_id uuid NOT NULL REFERENCES users(id), import_provider text NOT NULL DEFAULT 'manual', external_guild_id text, last_roster_sync_at timestamptz, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS guild_workspace_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK (role IN ('owner','officer','raid-leader','member')), capabilities jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,user_id));
CREATE TABLE IF NOT EXISTS guild_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds(id), character_id text NOT NULL, character_name text NOT NULL, class_name text NOT NULL, spec text NOT NULL DEFAULT '', level integer NOT NULL DEFAULT 60, race text NOT NULL DEFAULT '', faction text NOT NULL CHECK (faction IN ('Alliance','Horde')), realm text NOT NULL, region text NOT NULL CHECK (region IN ('eu','us')), realm_type text NOT NULL CHECK (realm_type IN ('era','anniversary')), content_version text NOT NULL CHECK (content_version IN ('era','tbc')), role text NOT NULL DEFAULT 'DPS', readiness text NOT NULL DEFAULT 'unknown' CHECK (readiness IN ('ready','needs-review','unknown')), gear_set_id text, active boolean NOT NULL DEFAULT true, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,character_id));
CREATE TABLE IF NOT EXISTS guild_member_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_member_id uuid NOT NULL REFERENCES guild_members(id), user_id uuid NOT NULL REFERENCES users(id), status text NOT NULL CHECK (status IN ('pending','approved','rejected','revoked')), verification_method text CHECK (verification_method IN ('officer-verified','battlenet-verified')), reviewed_by_user_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_member_id,user_id));
CREATE TABLE IF NOT EXISTS guild_main_alt_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds(id), main_member_id uuid NOT NULL REFERENCES guild_members(id), alt_member_id uuid NOT NULL REFERENCES guild_members(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,alt_member_id), CHECK(main_member_id <> alt_member_id));
CREATE TABLE IF NOT EXISTS raid_teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,name));
CREATE TABLE IF NOT EXISTS raid_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds(id), raid_team_id uuid REFERENCES raid_teams(id), name text NOT NULL, instance text NOT NULL, starts_at timestamptz NOT NULL, duration_minutes integer NOT NULL, status text NOT NULL CHECK(status IN ('draft','open','locked','complete')), raid_leader_user_id uuid REFERENCES users(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS raid_signups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), raid_event_id uuid NOT NULL REFERENCES raid_events(id), guild_member_id uuid NOT NULL REFERENCES guild_members(id), status text NOT NULL CHECK(status IN ('pending','confirmed','declined','waitlist')), note text NOT NULL DEFAULT '', updated_by_user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(raid_event_id,guild_member_id));
CREATE TABLE IF NOT EXISTS raid_roster_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), raid_event_id uuid NOT NULL REFERENCES raid_events(id), guild_member_id uuid NOT NULL REFERENCES guild_members(id), roster_state text NOT NULL CHECK(roster_state IN ('selected','bench')), group_name text, position integer, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(raid_event_id,guild_member_id));
CREATE TABLE IF NOT EXISTS raid_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), raid_event_id uuid NOT NULL REFERENCES raid_events(id), label text NOT NULL, detail text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS raid_assignment_assignees (assignment_id uuid NOT NULL REFERENCES raid_assignments(id), guild_member_id uuid NOT NULL REFERENCES guild_members(id), PRIMARY KEY(assignment_id,guild_member_id));
CREATE TABLE IF NOT EXISTS raid_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guild_id uuid NOT NULL REFERENCES guilds(id), name text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES users(id), guild_id uuid REFERENCES guilds(id), entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, summary jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS guild_members_guild_active_idx ON guild_members(guild_id,active);
CREATE INDEX IF NOT EXISTS raid_events_guild_start_idx ON raid_events(guild_id,starts_at);
CREATE INDEX IF NOT EXISTS audit_events_guild_created_idx ON audit_events(guild_id,created_at DESC);
